def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    pillows = image_patch.find("pillow")

    if not chairs or not pillows:
        return image_patch

    front_left_chairs = [c for c in chairs if c.horizontal_center < image_patch.width / 2 and c.vertical_center < image_patch.height / 2]
    front_left_pillow_areas = [p for p in pillows if p.horizontal_center < image_patch.width / 2 and p.vertical_center < image_patch.height / 2]

    valid_chairs = [c for c in front_left_chairs if all(not is_overlapping(c, p) for p in front_left_pillow_areas)]

    return valid_chairs[0] if valid_chairs else chairs[0]

def is_overlapping(patch_a: ImagePatch, patch_b: ImagePatch) -> bool:
    return not (patch_a.right <= patch_b.left or patch_a.left >= patch_b.right or patch_a.upper >= patch_b.lower or patch_a.lower <= patch_b.upper)

