def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bread_patches = image_patch.find("bread")
    bacon_patches = image_patch.find("bacon")

    if not bread_patches or not bacon_patches:
        return image_patch

    bottom_bread = min(bread_patches, key=lambda p: p.vertical_center)
    top_bacon = max(bacon_patches, key=lambda p: p.vertical_center)

    if bottom_bread.vertical_center < top_bacon.vertical_center:
        return bottom_bread
    else:
        return top_bacon

